  rule_direction_v4:{id:'rule_direction_v4',source:'docs/releases/KM-DIRECTION-4.0.md',verification:'source_profiled_direction_overlay',conditions:'KM-DIRECTION-4.0 bổ sung Địa Tư Môn, Đình Đình/Bạch Gian, Thiên Mã/Thiên Cương và Tam Thắng/Ngũ Bất Kích. Đây là annotation phương vị có provenance; không tham gia evidenceScore, không đổi primaryJudgment/rank, và mọi ngôn ngữ quân sự cổ được chuẩn hóa thành thế đứng/tránh đối đầu trực diện.'},
  rule_nianming_v1:{id:'rule_nianming_v1',source:'docs/releases/KM-NIANMING-1.0.md',verification:'classical_auxiliary_plus_modern_year_stem_convention',conditions:'KM-NIANMING-1.0 chỉ dùng Niên Mệnh do người dùng tự cung cấp như corroborator. Can niên trụ được định vị trên thiên bàn hiện tại; chi năm sinh chỉ tham chiếu phụ. Không thay Nhật can, Dụng Thần primary/secondary, không tham gia evidenceScore hoặc primaryJudgment và không biến người unresolved thành đã xác nhận.'},
  rule_role_v2:{id:'rule_role_v2',source:'docs/releases/KM-ROLE-2.0.md',verification:'contextual_host_guest_with_app_agency',conditions:'KM-ROLE-2.0 coi Chủ–Khách là tư thế theo sự việc, không phải danh tính cố định; Nội/Ngoại chỉ là xu hướng gần–xa/nhanh–chậm; agency và chiều tác động là lớp tổng hợp biểu tượng, không xác minh quyền lực, ý chí hoặc bên thắng/thua ngoài thực tế.'},
  rule_timeplace_v2:{id:'rule_timeplace_v2',source:'docs/releases/KM-TIMEPLACE-2.0.md',verification:'iana_civil_opt_in_solar_metadata_only',conditions:'KM-TIMEPLACE-2.0 mặc định giữ fixed UTC offset. IANA civil mode là opt-in và resolve offset lịch sử/DST; giờ DST bị lặp cần disambiguation, giờ không tồn tại bị chặn. Tọa độ/giờ Mặt Trời chỉ là metadata và không tự đổi giờ lập bàn.'},
